import {
  Bot, Pencil, Plus, ChevronDown, Trash2,
  Search, PenLine, Eye, FileText, Send, Cpu,
} from 'lucide-react';
import { agentsApi } from '../api/agents';
import { AgentCreateModal, AgentEditorModal } from '../components/agents/AgentEditorModal';
import { useProjectStore } from '../store/projectStore';
import toast from 'react-hot-toast';
import { translate, useTranslation } from '../i18n';

//: Agentes de serie de los **otros** tipos de proyecto que la plataforma siembra
//: (desarrollo, marketing, tiqueting, diseño). Siguen aquí porque esos tipos
//: todavía no tienen `template.yaml`: viven como listas en
//: `backend/app/shared/agents_seed.py`. Cuando se empaqueten, esta lista se
//: vacía igual que se vació la de AlejandrIA.
const OTHER_PROJECT_TYPE_SLUGS = [
  'orquestador',
  'arquitecto', 'backend-dev', 'frontend-dev', 'qa-tester', 'devops', 'code-reviewer',
  'estratega', 'copywriter', 'social-media', 'seo-specialist', 'analista',
  'clasificador', 'agente-soporte', 'escalador', 'resolutor', 'qa-calidad',
  'art-director', 'ui-designer', 'ux-researcher', 'revisor-visual', 'motion-designer',
];

//: Los del proyecto activo salen de su catálogo; el resto, del residuo de arriba.
const builtinSlugs = () => new Set([...agentIds(), ...OTHER_PROJECT_TYPE_SLUGS]);

const RESIDUAL_META = {
  // Los cinco de AlejandrIA ya no están aquí: los aporta su catálogo (T8.6).
  orquestador:     { icon: Cpu,      color: 'var(--blue-60)' },
  // Desarrollo
  arquitecto:      { color: 'var(--agent-format)' },
  'backend-dev':   { color: 'var(--agent-format)' },
  'frontend-dev':  { color: 'var(--agent-format)' },
  'qa-tester':     { color: 'var(--agent-format)' },
  devops:          { color: 'var(--agent-format)' },
  'code-reviewer': { color: 'var(--agent-format)' },
  // Marketing
  estratega:       { color: 'var(--agent-review)' },
  copywriter:      { color: 'var(--agent-review)' },
  'social-media':  { color: 'var(--agent-review)' },
  'seo-specialist':{ color: 'var(--agent-review)' },
  analista:        { color: 'var(--agent-review)' },
  // Tiqueting
  clasificador:    { color: 'var(--agent-research)' },
  'agente-soporte':{ color: 'var(--agent-research)' },
  escalador:       { color: 'var(--agent-research)' },
  resolutor:       { color: 'var(--agent-research)' },
  'qa-calidad':    { color: 'var(--agent-research)' },
  // Diseño
  'art-director':  { color: 'var(--agent-write)' },
  'ui-designer':   { color: 'var(--agent-write)' },
  'ux-researcher': { color: 'var(--agent-write)' },
  'revisor-visual':{ color: 'var(--agent-write)' },
  'motion-designer':{ color: 'var(--agent-write)' },
};

//: Igual con los metadatos: primero el catálogo del proyecto.
const builtinMeta = (slug) => ({ ...(RESIDUAL_META[slug] || {}), ...agentMeta(slug) });

// ---------------------------------------------------------------------------
// ModelSelector dropdown
// ---------------------------------------------------------------------------

function ModelSelector({ value, onChange, models }) {
  const { t } = useTranslation();
  const [open, setOpen] = useState(false);
  const ref = useRef(null);

  useEffect(() => {
    const handler = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  return (
    <div ref={ref} style={{ position: 'relative' }}>
      <button
        type="button"
        className="input"
        onClick={() => setOpen(o => !o)}
        style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', cursor: 'pointer', textAlign: 'left' }}
        aria-haspopup="listbox"
        aria-expanded={open}
      >
        <span>{value || t('agentsPage.selectModel')}</span>
        <ChevronDown size={14} style={{ flexShrink: 0, color: 'var(--text-muted)' }} />
      </button>
      {open && (
        <ul
          role="listbox"
          style={{
            position: 'absolute', top: '100%', left: 0, right: 0, zIndex: 50,
            background: 'var(--bg-card)', border: '1px solid var(--border-subtle)',
            borderRadius: 'var(--radius-md)', listStyle: 'none', margin: '4px 0 0',
            padding: '4px 0', maxHeight: 200, overflowY: 'auto',
            boxShadow: '0 8px 24px rgba(0,0,0,0.3)',
          }}
        >
          {models.map(m => (
            <li
              key={m}
              role="option"
              aria-selected={m === value}
              onClick={() => { onChange(m); setOpen(false); }}
              style={{
                padding: '7px 14px', cursor: 'pointer', fontSize: 'var(--font-size-sm)',
                background: m === value ? 'var(--bg-overlay)' : 'transparent',
                color: m === value ? 'var(--brand-primary)' : 'var(--text-primary)',
              }}
            >
              {m}
            </li>
          ))}
          <li style={{ borderTop: '1px solid var(--border-subtle)', padding: '4px 8px' }}>
            <input
              className="input"
              placeholder={t('agentsPage.otherModel')}
              style={{ fontSize: 'var(--font-size-xs)', padding: '4px 8px' }}
              aria-label={t('agentsPage.customModelName')}
              onKeyDown={e => {
                if (e.key === 'Enter' && e.target.value.trim()) {
                  onChange(e.target.value.trim());
                  setOpen(false);
                }
              }}
            />
          </li>
        </ul>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Agent card
